content:
{
  "findings": [
    {
      "title": "Sample size calculation inconsistency: 69 subjects for 90% power but 100 planned, with no clear justification for the increase beyond 15% discontinuation",
      "page": 11,
      "quote": "A sample size of 69 subjects achieves at least 90% power to detect a difference of 13% using a 2-sided exact test with a significance level of 0.05, assuming that the null hypothesis for ORR is 7% (Hodi-2016; Ribas-2018), and the study ORR is 20%. The sample size was increased to 100 subjects to adjust for an early discontinuation rate of 15%, and to allow for a robust assessment of safety.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 4c requires documented progression in previously radiated lesion, but this is not a standard RECIST requirement and may contradict other criteria",
      "page": 7,
      "quote": "c. Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 5 allows archival sample if no intervening therapy, but this is not clearly defined and may conflict with the requirement for fresh biopsy",
      "page": 7,
      "quote": "A fresh tissue biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable (as a substitute) if no intervening therapy was received.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 18 prohibits colony stimulating factors within 30 days before Screening, but Screening may occur before baseline labs, creating ambiguity",
      "page": 9,
      "quote": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 30 days before the start of Screening.",
      "severity": "minor"
    },
    {
      "title": "Treatment duration says maximum 2 years, but no explicit stopping rule for subjects who achieve CR earlier than 48 weeks",
      "page": 10,
      "quote": "Treatment will be given for a maximum of 2 years from the start of study treatment. If a subject achieves and maintains a confirmed CR or immune complete response (iCR) by investigator review, treatment with CMP-001 or the combination of CMP-001 and nivolumab may be discontinued at the Investigator’s discretion once they meet both of the following criteria: • Subject has been treated with both study treatments for at least 48 weeks • Subject has received at least 3 doses of both study treatments beyond the date of the initial CR/iCR",
      "severity": "minor"
    },
    {
      "title": "Pharmacokinetic assessment says serum CMP-001 levels, but later says blood concentrations; inconsistent matrix",
      "page": 11,
      "quote": "Pharmacokinetic assessment will be performed in order to assess serum CMP-001 levels following IT injection and potentially SC administration in the first 20 subjects enrolled.",
      "severity": "minor"
    },
    {
      "title": "Immunogenicity endpoint says anti-Qb antibodies, but synopsis says anti-Qbeta (Qb) antibodies; inconsistent terminology",
      "page": 6,
      "quote": "Development of anti-Qbeta (Qb) antibodies",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 7a lists white blood cells ≥ 2000/mm3, but this is not a standard bone marrow function criterion and may be redundant with neutrophil count",
      "page": 7,
      "quote": "− white blood cells ≥ 2000/mm3",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 4c references Section 5.1.2.1.1. for stress-dose corticosteroids, but the protocol does not contain that section in the excerpt",
      "page": 8,
      "quote": "c. Stress-dose corticosteroids will be required in subjects with adrenal insufficiency (see Section 5.1.2.1.1.).",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 11 references Section 4.3.2. for contraception, but the protocol excerpt does not include that section",
      "page": 8,
      "quote": "be willing to use an adequate method of contraception (Section 4.3.2.)",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 3 references Section 4.4. for prohibited therapies, but the protocol excerpt does not include that section",
      "page": 8,
      "quote": "Refer to Section 4.4. for prohibited therapies.",
      "severity": "minor"
    },
    {
      "title": "The protocol states 'A subject is enrolled in the study when they have received the first dose of study treatment' but also says 'Number of subjects (planned): 100' and 'The study will enroll approximately 100 subjects' - this is consistent, but the sample size calculation uses 69 subjects, which is not clearly linked to the 100 planned",
      "page": 11,
      "quote": "The study will enroll approximately 100 subjects. A subject is enrolled in the study when they have received the first dose of study treatment.",
      "severity": "minor"
    }
  ]
}
